const legacyDomainAliases = Object.freeze({ system: 'infrastructure', network: 'infrastructure' })
const researchRoleDomainOverrides = Object.freeze({ 'research-embedded-security': 'iot-embedded', 'research-automotive-security': 'automotive' })
const researchRoleFamilyOverrides = Object.freeze({ 'research-embedded-security': 'family-iot-embedded', 'research-automotive-security': 'family-automotive' })

function normalizeResearchDomainId(id) {
  return legacyDomainAliases[id] || id
}

function role({ id, domainId, linkedDomainIds = [], familyId, title, rawTitles, summary, actualWork, deliverables, foundations, learningAxes, evidenceLevel, sources = [], limitations = '' }) {
  return Object.freeze({
    id,
    domainId: researchRoleDomainOverrides[id] || normalizeResearchDomainId(domainId),
    linkedDomainIds: [...new Set(linkedDomainIds.map(normalizeResearchDomainId))],
    familyId: researchRoleFamilyOverrides[id] || familyId,
    title,
    rawTitles,
    summary,
    actualWork,
    deliverables,
    foundations,
    learningAxes,
    evidence: Object.freeze({ level: evidenceLevel, label: researchEvidenceLabels[evidenceLevel], sources, reportSource, limitations }),
  })
}

