const researchRoleLookup = Object.freeze(Object.fromEntries(researchRoles.map((item) => [item.id, item])))

function catalog(domainId, entries) {
  return entries.map(([id, title, summary, detailRoleId = null, relatedDomainIds = [], workContext = '']) => Object.freeze({
    id: `catalog-${id}`,
    domainId,
    title,
    summary,
    detailRoleId,
    relatedDomainIds: [...new Set(relatedDomainIds)],
    workContext,
    evidence: Object.freeze({
      level: detailRoleId ? researchRoleLookup[detailRoleId]?.evidence.level || 'industryResearch' : 'industryResearch',
      label: detailRoleId ? researchRoleLookup[detailRoleId]?.evidence.label || researchEvidenceLabels.industryResearch : '리서치 보고서의 대표 역할',
      source: detailRoleId ? '상세 근거 카드 연결' : '보고서의 분야별 역할 목록',
    }),
  }))
}

