export const representativeRolesByDomain = Object.freeze(Object.fromEntries(researchDomains.map((domain) => [domain.id, representativeRoleCatalog.filter((role) => role.domainId === domain.id)])))

export function representativeRolesForDomain(domainId) {
  return representativeRolesByDomain[domainId] || []
}

export function representativeRoleGroupsForDomain(domainId) {
  return representativeRoleGroups.filter((group) => group.domainId === domainId)
}

export const researchDomainById = Object.freeze(Object.fromEntries(researchDomains.map((item) => [item.id, item])))
export const researchFamilyById = Object.freeze(Object.fromEntries(researchJobFamilies.map((item) => [item.id, item])))
export const researchRoleById = researchRoleLookup

export function researchFamiliesForDomain(domainId) {
  return researchJobFamilies.filter((item) => item.domainId === domainId)
}

export function researchRolesForDomain(domainId) {
  return researchRoles.filter((item) => item.domainId === domainId || item.linkedDomainIds.includes(domainId))
}

export function researchRolesForFamily(familyId) {
  return researchRoles.filter((item) => item.familyId === familyId)
}
